function solve(num, k) {
  const st = [];
  for (const ch of num) {
    while (k > 0 && st.length && st[st.length - 1] > ch) {
      st.pop();
      k--;
    }
    st.push(ch);
  }
  while (k-- > 0) st.pop();
  let i = 0;
  while (i < st.length && st[i] === '0') i++;
  const out = st.slice(i).join('');
  return out === '' ? '0' : out;
}
